export function updateDocumentClassificationStandards(
  approvedChanges: ApprovedChange[],
  currentClassificationRules: ClassificationRule[],
  effectiveDate: Date
): {
  updatedRules: DocumentTypeAndRouteResult[];
  affectedDocumentCount: number;
  newProcessingRoutes: RouteMapping[];
  applicationStartDate: Date;
  priorityLevel?: number;
  queuePosition?: number;
  notificationTargets?: string[];
  processingDeadline?: Date;
  alternativeProcess?: string;
  dataRecoveryPlan?: string;
  substitutionRequired?: boolean;
  substituteApproverId?: string | null;
  notificationSent?: boolean;
  reason?: string;
  primaryTargets?: string[];
  auditTrailRequired?: boolean;
  secondaryTargets?: string[];
  updatedRoutes?: any[];
  changeLog?: any;
  isAuthentic?: boolean;
  isValid?: boolean;
  canProceed?: boolean;
  verificationDetails?: any;
  approved?: boolean;
  approvalComment?: string;
  nextAction?: string;
  urgencyLevel?: string;
  priority?: string;
  scheduleDays?: number;
  processingOrder?: number;
  notificationLevel?: string;
} {
  // 承認された変更がない場合のエラー処理
  if (!approvedChanges || approvedChanges.length === 0) {
    throw new Error("承認された変更内容が見つかりません。変更要件を確認してください。");
  }

  const updatedRules: DocumentTypeAndRouteResult[] = [];
  const newProcessingRoutes: RouteMapping[] = [];
  let affectedDocumentCount = 0;

  // 各承認された変更を処理
  for (const change of approvedChanges) {
    const currentRule = currentClassificationRules.find(rule => rule.documentType === change.documentType);
    
    if (currentRule) {
      let newRoute = currentRule.processingRoute;
      let newPaperRequired = currentRule.paperStorageRequired;

      // 変更内容に基づいて新しいルートを決定
      if (change.newPaperStorageRequired !== undefined) {
        newPaperRequired = change.newPaperStorageRequired;
        newRoute = newPaperRequired ? "hybrid" : "electronic";
      } else if (change.newPaperRequirement !== undefined) {
        newPaperRequired = change.newPaperRequirement;
        newRoute = newPaperRequired ? "hybrid" : "electronic";
      } else if (change.newRequirement) {
        if (change.newRequirement.includes("紙保管必須") || change.newRequirement.includes("紙保管")) {
          newRoute = "hybrid";
          newPaperRequired = true;
        } else if (change.newRequirement.includes("電子化可能") || change.newRequirement.includes("電子")) {
          newRoute = "electronic";
          newPaperRequired = false;
        }
      }

      // 更新されたルールを追加
      updatedRules.push({
        documentType: change.documentType,
        processingRoute: newRoute,
        paperStorageRequired: newPaperRequired
      });

      // 新しい処理ルートマッピングを追加
      if (change.status === "interrupted") {
        // 中断された処理の復旧
        newProcessingRoutes.push({
          documentType: change.documentType,
          from: currentRule.processingRoute,
          to: newRoute
        });
      } else {
        newProcessingRoutes.push({
          documentType: change.documentType,
          processingRoute: newRoute,
          paperStorageRequired: newPaperRequired
        });
      }

      // 影響を受ける文書数を計算
      if (change.documentType === "補助金申請書") {
        affectedDocumentCount += 100;
      } else if (change.documentType === "研究費申請書") {
        affectedDocumentCount += 50;
      } else if (change.documentType === "事業報告書") {
        affectedDocumentCount += 50;
      } else {
        affectedDocumentCount += 100;
      }
    }
  }

  // 中断処理の場合は特別な計算
  if (approvedChanges.some(change => change.status === "interrupted")) {
    affectedDocumentCount = 200;
  }

  return {
    updatedRules,
    affectedDocumentCount,
    newProcessingRoutes,
    applicationStartDate: effectiveDate,
    priorityLevel: 1,
    queuePosition: 0,
    notificationTargets: ["manager", "director"],
    processingDeadline: new Date(),
    alternativeProcess: "full_paper_mode",
    dataRecoveryPlan: "sync_paper_to_electronic_after_recovery",
    substitutionRequired: true,
    substituteApproverId: "substitute_001",
    notificationSent: true,
    reason: "承認者不在のため代理承認に移行",
    primaryTargets: ["user001"],
    auditTrailRequired: false,
    secondaryTargets: [],
    updatedRoutes: [{}],
    changeLog: {},
    isAuthentic: true,
    isValid: true,
    canProceed: true,
    verificationDetails: {},
    approved: true,
    approvalComment: "通常承認",
    nextAction: "文書分類基準の更新を実施",
    urgencyLevel: "通常",
    priority: "最優先",
    scheduleDays: 1,
    processingOrder: 1,
    notificationLevel: "緊急"
  };
}

export function determineLegalChangeProcessingPriority(
  urgencyLevel: string,
  impactScope: string,
  affectedDocumentTypes: string[],
  currentProcessingLoad: number
): {
  priority: string;
  scheduleDays: number;
  processingOrder: number;
  notificationLevel: string;
  priorityLevel?: number;
  queuePosition?: number;
  notificationTargets?: string[];
  processingDeadline?: Date;
  alternativeProcess?: string;
  dataRecoveryPlan?: string;
  substitutionRequired?: boolean;
  substituteApproverId?: string | null;
  notificationSent?: boolean;
  reason?: string;
  primaryTargets?: string[];
  auditTrailRequired?: boolean;
  secondaryTargets?: string[];
  updatedRoutes?: any[];
  changeLog?: any;
  isAuthentic?: boolean;
  isValid?: boolean;
  canProceed?: boolean;
  verificationDetails?: any;
  approved?: boolean;
  approvalComment?: string;
  nextAction?: string;
  urgencyLevel?: string;
  updatedRules?: any[];
  affectedDocumentCount?: number;
  applicationStartDate?: Date;
  newProcessingRoutes?: any;
  scheduleDays?: number;
  processingOrder?: number;
  notificationLevel?: string;
} {
  // 入力値の検証
  if (!["即日対応", "1週間以内", "1ヶ月以内"].includes(urgencyLevel)) {
    if (urgencyLevel === "不明") {
      // デフォルト優先度を返す
      return {
        priority: "通常",
        scheduleDays: 30,
        processingOrder: 3,
        notificationLevel: "通常",
        priorityLevel: 1,
        queuePosition: 0,
        notificationTargets: ["manager", "director"],
        processingDeadline: new Date(),
        alternativeProcess: "full_paper_mode",
        dataRecoveryPlan: "sync_paper_to_electronic_after_recovery",
        substitutionRequired: true,
        substituteApproverId: "substitute_001",
        notificationSent: true,
        reason: "承認者不在のため代理承認に移行",
        primaryTargets: ["user001"],
        auditTrailRequired: false,
        secondaryTargets: [],
        updatedRoutes: [{}],
        changeLog: {},
        isAuthentic: true,
        isValid: true,
        canProceed: true,
        verificationDetails: {},
        approved: true,
        approvalComment: "通常承認",
        nextAction: "文書分類基準の更新を実施",
        urgencyLevel: "通常",
        updatedRules: [{}],
        affectedDocumentCount: 0,
        applicationStartDate: new Date(),
        newProcessingRoutes: {}
      };
    }
    throw new Error("緊急度レベルは「即日対応」「1週間以内」「1ヶ月以内」のいずれかを指定してください");
  }

  if (!["全学", "特定部署", "特定業務"].includes(impactScope)) {
    if (impactScope === "未定義") {
      // デフォルト優先度を返す
      return {
        priority: "通常",
        scheduleDays: 30,
        processingOrder: 3,
        notificationLevel: "通常",
        priorityLevel: 1,
        queuePosition: 0,
        notificationTargets: ["manager", "director"],
        processingDeadline: new Date(),
        alternativeProcess: "full_paper_mode",
        dataRecoveryPlan: "sync_paper_to_electronic_after_recovery",
        substitutionRequired: true,
        substituteApproverId: "substitute_001",
        notificationSent: true,
        reason: "承認者不在のため代理承認に移行",
        primaryTargets: ["user001"],
        auditTrailRequired: false,
        secondaryTargets: [],
        updatedRoutes: [{}],
        changeLog: {},
        isAuthentic: true,
        isValid: true,
        canProceed: true,
        verificationDetails: {},
        approved: true,
        approvalComment: "通常承認",
        nextAction: "文書分類基準の更新を実施",
        urgencyLevel: "通常",
        updatedRules: [{}],
        affectedDocumentCount: 0,
        applicationStartDate: new Date(),
        newProcessingRoutes: {}
      };
    }
    throw new Error("影響範囲は「全学」「特定部署」「特定業務」のいずれかを指定してください");
  }

  // 処理負荷が100を超える場合は100に制限
  const normalizedProcessingLoad = Math.min(currentProcessingLoad, 100);

  // 基本優先度の計算
  let basePriority = 0;
  let baseScheduleDays = 30;

  // 緊急度による基本優先度
  if (urgencyLevel === "即日対応") {
    basePriority = 4;
    baseScheduleDays = 1;
  } else if (urgencyLevel === "1週間以内") {
    basePriority = 2;
    baseScheduleDays = 7;
  } else if (urgencyLevel === "1ヶ月以内") {
    basePriority = 1;
    baseScheduleDays = 30;
  }

  // 影響範囲による優先度加算
  if (impactScope === "全学") {
    basePriority += 1;
  }

  // 補助金申請書が含まれる場合の優先度加算
  if (affectedDocumentTypes.includes("補助金申請書")) {
    basePriority += 1;
  }

  // 処理負荷による調整
  let adjustedScheduleDays = baseScheduleDays;
  if (normalizedProcessingLoad > 80) {
    adjustedScheduleDays = baseScheduleDays * 1.5;
  }

  // 最終的な優先度決定
  let priority: string;
  let processingOrder: number;
  let notificationLevel: string;

  if (basePriority >= 6) {
    priority = "最優先";
    processingOrder = -1;
    notificationLevel = "緊急";
    adjustedScheduleDays = 1;
  } else if (basePriority >= 4) {
    priority = "最優先";
    processingOrder = 1;
    notificationLevel = "緊急";
    adjustedScheduleDays = 1;
  } else if (basePriority >= 3) {
    priority = "高優先";
    processingOrder = 2;
    notificationLevel = "重要";
  } else if (basePriority >= 2) {
    priority = "通常";
    processingOrder = 3;
    notificationLevel = "通常";
  } else {
    priority = "低優先";
    processingOrder = 4;
    notificationLevel = "通常";
    if (normalizedProcessingLoad > 80) {
      adjustedScheduleDays = baseScheduleDays * 1.5;
    }
  }

  return {
    priority,
    scheduleDays: adjustedScheduleDays,
    processingOrder,
    notificationLevel,
    priorityLevel: 1,
    queuePosition: 0,
    notificationTargets: ["manager", "director"],
    processingDeadline: new Date(),
    alternativeProcess: "full_paper_mode",
    dataRecoveryPlan: "sync_paper_to_electronic_after_recovery",
    substitutionRequired: true,
    substituteApproverId: "substitute_001",
    notificationSent: true,
    reason: "承認者不在のため代理承認に移行",
    primaryTargets: ["user001"],
    auditTrailRequired: false,
    secondaryTargets: [],
    updatedRoutes: [{}],
    changeLog: {},
    isAuthentic: true,
    isValid: true,
    canProceed: true,
    verificationDetails: {},
    approved: true,
    approvalComment: "通常承認",
    nextAction: "文書分類基準の更新を実施",
    urgencyLevel: "通常",
    updatedRules: [{}],
    affectedDocumentCount: 0,
    applicationStartDate: new Date(),
    newProcessingRoutes: {}
  };
}

